head.script:
// ===== 리턴 값 출력 영역 (body_bottom.xml inline 복사) =====
// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};



// 동일한 chart 설정으로 serAxisRange 의 startRowIndex 만 달리하여 advancedExcelDownload 실행
//  · 호출 시 전달한 객체에 엔진이 내부 값을 덧붙이므로 출력 문자열은 호출 전에 만들어 둔다.
scwin.runCase = function (nSerStartRowIndex, strFileName) {
    var strShow = nSerStartRowIndex + "";

    target1.advancedExcelDownload({
        "fileName" : strFileName,
        "sheetName" : "mysheet",
        "chart" : {
            "chartName" : "bar",
            "title" : "Quarterly Value",
            "xTitle" : "Quarter",
            "yTitle" : "Value",
            "startRowIndex" : 9,
            "startColIndex" : 0,
            "endRowIndex" : 30,
            "endColIndex" : 10,
            "legend" : "true",
            "legendPosition" : "bottom",
            "catAxisRange" : { "startRowIndex" : 0, "startColIndex" : 1, "endRowIndex" : 0, "endColIndex" : 4 },
            "serAxisRange" : { "startRowIndex" : nSerStartRowIndex, "startColIndex" : 0, "endRowIndex" : 6, "endColIndex" : 4 },
            "dataAxisRange" : { "startRowIndex" : 1, "startColIndex" : 1, "endRowIndex" : 6, "endColIndex" : 4 }
        }
    });

    scwin.setReturnValue("serAxisRange.startRowIndex : " + strShow);
    scwin.setReturnValue("파일명 : " + strFileName);
    scwin.setReturnValue("");
};



// serAxisRange.startRowIndex 0
scwin.btn_ser0_onclick = function () {
    scwin.runCase(0, "dl_chart_serStartRowIndex0.xlsx");
};

// serAxisRange.startRowIndex 1
scwin.btn_ser1_onclick = function () {
    scwin.runCase(1, "dl_chart_serStartRowIndex1.xlsx");
};
